import { ReactNode, FC } from 'react';

interface CheckboxProps {
    /** 是否选中 (受控) */
    checked?: boolean;
    /** 默认是否选中 (非受控) */
    defaultChecked?: boolean;
    /** 是否禁用 */
    disabled?: boolean;
    /** 半选状态 (用于全选场景) */
    indeterminate?: boolean;
    /** 选框值 */
    value?: string | number;
    /** 选中状态变化回调 */
    onChange?: (checked: boolean) => void;
    /** 选框形状 */
    shape?: 'square' | 'round';
    /** 选框位置 */
    iconPosition?: 'left' | 'right';
    /** 选中颜色 */
    checkedColor?: string;
    /** 自定义类名 */
    className?: string;
    /** 子元素 (标签文字) */
    children?: ReactNode;
}
interface CheckboxGroupProps {
    /** 选中的值 (受控) */
    value?: (string | number)[];
    /** 默认选中的值 (非受控) */
    defaultValue?: (string | number)[];
    /** 是否禁用所有选框 */
    disabled?: boolean;
    /** 最大可选数量 */
    max?: number;
    /** 排列方向 */
    direction?: 'horizontal' | 'vertical';
    /** 值变化回调 */
    onChange?: (value: (string | number)[]) => void;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

type CheckboxComponent = FC<CheckboxProps> & {
    Group: FC<CheckboxGroupProps>;
};
declare const Checkbox: CheckboxComponent;
declare const CheckboxGroup: FC<CheckboxGroupProps>;

export { Checkbox, CheckboxGroup, Checkbox as default };
export type { CheckboxGroupProps, CheckboxProps };
